// @minecraft/server-ui の最小スタブ。
// テストからは scripted な応答を仕込んで show() の戻り値を制御する。
export const FormCancelationReason = { UserBusy: "UserBusy", UserClosed: "UserClosed" };

export const formLog = [];
/** show() が返す応答をここに順番に積む。空なら canceled 扱い。 */
export const responses = [];

class BaseForm {
  constructor(kind) {
    this.kind = kind;
    this.spec = { kind, buttons: [], fields: [] };
  }
  title(t) {
    this.spec.title = t;
    return this;
  }
  body(b) {
    this.spec.body = b;
    return this;
  }
  button(b) {
    this.spec.buttons.push(b);
    return this;
  }
  textField(l, p, o) {
    this.spec.fields.push({ type: "text", label: l, placeholder: p, options: o });
    return this;
  }
  toggle(l, o) {
    this.spec.fields.push({ type: "toggle", label: l, options: o });
    return this;
  }
  dropdown(l, opts, o) {
    this.spec.fields.push({ type: "dropdown", label: l, choices: opts, options: o });
    return this;
  }
  slider(l, min, max, o) {
    this.spec.fields.push({ type: "slider", label: l, min, max, options: o });
    return this;
  }
  show() {
    formLog.push(this.spec);
    const next = responses.shift();
    return Promise.resolve(next ?? { canceled: true, cancelationReason: FormCancelationReason.UserClosed });
  }
}

export class ActionFormData extends BaseForm {
  constructor() {
    super("action");
  }
}
export class ModalFormData extends BaseForm {
  constructor() {
    super("modal");
  }
}
